import * as React from "react";
import "./ColumnsNavigation.scss";
import NormalTextLink from "../normalTextLink/NormalTextLink";

export interface ColumnsNavigationProps {
  /**
   * Unique identifier for the column navigation
   */
  id: string;

  /**
   * Array of menu sections. Each section may contain a label, link, and optional nested sub-menu items.
   */
  menuItems: {
    label: string;
    link?: string;
    subMenuItems?: ColumnsNavigationProps["menuItems"];
  }[];

  /**
   * Visual theme variant for the navigation component.
   * - "default": Light theme (default)
   * - "inverse": Dark theme
   */
  variant?: "default" | "inverse"; 

  /**
   * Index of the currently open/active column (used for expanding/collapsing logic).
   */
  /* openItem?: number ; */

  /**
   * Index of this navigation instance (used for comparison with `openItem` to determine open state).
   */
  /* index?: number; */
}

const ColumnsNavigation: React.FC<ColumnsNavigationProps> = ({
  id,
  variant = "default",
  menuItems = [],
  /* openItem,
   index */
}) => {

  const limitedNavigationData = menuItems.slice(0, 6);

  return (

      /* <div id={id} className={`columns-navigation columns ${openItem} ${index} ${variant} ${openItem === index ? 'open' : 'closed' } `}> */
      <div id={id} className={`columns-navigation columns ${variant} `}>
          {limitedNavigationData.map((section, index) => (
              <div key={index} className={`column-navigation `}  >
                {section?.label && <h3 className="column-header">{section.label}</h3>}
                {section.subMenuItems && (
                  <ul className={`column-menu ${!section?.label ? 'no-header' : ''}`}>
                    {section.subMenuItems.map((submenu, id) => (
                      <li key={id} className="submenu-item">
                        <NormalTextLink id={"normalTextLinkId"} href={submenu.link} className="submenu-link" target="_self">{submenu.label}</NormalTextLink>
                               
                      </li>
                    ))}
                  </ul>
                )}
              </div>
          ))}
      </div>
 

  );
};

export default ColumnsNavigation;

